package io.github.diodeme.ji.relay.protocol;

import java.util.Map;

/** Stable Relay management and routing error independent from user-facing text. */
public record RelayError(String code, Map<String, String> parameters) {
    public RelayError {
        if (code == null || code.isBlank()) throw new IllegalArgumentException("code must not be blank");
        parameters = Map.copyOf(parameters);
    }
}
